CREATE OR REPLACE FUNCTION public.block_unreviewed_compliance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF (TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.decision = 'Approved')) AND EXISTS (SELECT 1 FROM public.compliance_flags f WHERE f.application_id=NEW.application_id AND f.review_status <> 'Cleared') THEN RAISE EXCEPTION 'Compliance flag requires human clearance before approval'; END IF; RETURN NEW; END $$;
CREATE TRIGGER tradeflow_compliance_guard BEFORE INSERT OR UPDATE ON public.approvals FOR EACH ROW EXECUTE FUNCTION public.block_unreviewed_compliance();